#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

long long power(long long base, long long e) {
    long long r = 1;
    for (base %= MOD; e > 0; e >>= 1, base = base * base % MOD)
        if (e & 1) r = r * base % MOD;
    return r;
}

int main() {
    string s;
    cin >> s;
    int n = s.size();
    vector<long long> cnt(26, 0);
    for (char c : s) cnt[c - 'a']++;
    vector<long long> fact(n + 1, 1), inv(n + 1, 1);
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
    inv[n] = power(fact[n], MOD - 2);
    for (int i = n - 1; i >= 0; i--) inv[i] = inv[i + 1] * (i + 1) % MOD;
    long long answer = 0, top = *max_element(cnt.begin(), cnt.end());
    // common frequency k: each letter either takes C(count, k) index sets or is absent
    for (long long k = 1; k <= top; k++) {
        long long product = 1;
        for (long long c : cnt)
            if (c >= k) product = product * (fact[c] * inv[k] % MOD * inv[c - k] % MOD + 1) % MOD;
        answer = (answer + product - 1 + MOD) % MOD;  // drop the empty choice
    }
    cout << answer << "\n";
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static final long MOD = 1000000007L;

    static long power(long base, long e) {
        long r = 1;
        for (base %= MOD; e > 0; e >>= 1, base = base * base % MOD)
            if ((e & 1) == 1) r = r * base % MOD;
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        String s = next();
        int n = s.length();
        int[] cnt = new int[26];
        for (int i = 0; i < n; i++) cnt[s.charAt(i) - 'a']++;
        long[] fact = new long[n + 1], inv = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        inv[n] = power(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; i--) inv[i] = inv[i + 1] * (i + 1) % MOD;
        int top = 0;
        for (int c : cnt) top = Math.max(top, c);
        long answer = 0;
        // common frequency k: each letter either takes C(count, k) index sets or is absent
        for (int k = 1; k <= top; k++) {
            long product = 1;
            for (int c : cnt)
                if (c >= k) product = product * (fact[c] * inv[k] % MOD * inv[c - k] % MOD + 1) % MOD;
            answer = (answer + product - 1 + MOD) % MOD; // drop the empty choice
        }
        System.out.println(answer);
    }
}

