var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

const mod = 1000000007

func power(base, e int64) int64 {
	r := int64(1)
	for base %= mod; e > 0; e >>= 1 {
		if e&1 == 1 {
			r = r * base % mod
		}
		base = base * base % mod
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
