	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}
	inv[n] = power(fact[n], mod-2)
	for i := n - 1; i >= 0; i-- {
		inv[i] = inv[i+1] * int64(i+1) % mod
	}
